KDPP3_PAYLOAD_BASE64
echo "$PAYLOAD_SHA256  $STAGE/payload.tar.gz" | sha256sum -c - >/dev/null || { echo FAIL_PAYLOAD_SHA256; exit 85; }
tar --warning=no-timestamp -xzf "$STAGE/payload.tar.gz" -C "$STAGE" || { echo FAIL_EXTRACT; exit 86; }
echo "PAYLOAD_OK sha256=$PAYLOAD_SHA256 bytes=$(stat -c %s "$STAGE/payload.tar.gz")"
"$PY" -I -B - "$STAGE" <<'KDPP3_VERIFY'
import hashlib, json, sys
root = sys.argv[1]
manifest = json.load(open(root + '/deploy_manifest.sha256.json'))
bad = [k for k, v in manifest.items() if hashlib.sha256(open(root + '/' + k, 'rb').read()).hexdigest() != v]
print('DEPLOY_MANIFEST members=%d mismatched=%d' % (len(manifest), len(bad)))
sys.exit(1 if bad else 0)
KDPP3_VERIFY
rc=$?; echo "VERIFY_EXIT=$rc"; [ "$rc" -eq 0 ] || exit 87
mv "$ROOT/workspace" "$ROOT/workspace_superseded_seq141" || exit 88
mv "$ROOT/launcher" "$ROOT/launcher_superseded_seq141" || exit 88
mv "$ROOT/resource_policy_v3.json" "$ROOT/resource_policy_v3_superseded_seq141.json" || exit 88
mv "$ROOT/deploy_manifest.sha256.json" "$ROOT/deploy_manifest_superseded_seq141.sha256.json" || exit 88
mv "$STAGE/workspace" "$ROOT/workspace" && mv "$STAGE/launcher" "$ROOT/launcher" && mv "$STAGE/resource_policy_v3.json" "$ROOT/resource_policy_v3.json" && mv "$STAGE/deploy_manifest.sha256.json" "$ROOT/deploy_manifest.sha256.json" || exit 89
rm -f "$STAGE/payload.tar.gz"; rmdir "$STAGE" 2>/dev/null; true
echo "WORKSPACE_FROZEN_MANIFEST_SHA256=$(sha256sum "$ROOT/workspace/frozen_members.sha256.json" | cut -c1-64)"
echo "MATRIX_SHA256=$(sha256sum "$ROOT/workspace/configs/aligned_v3/matrix.json" | cut -c1-64)"
echo "RESOURCE_BIND_SHA256=$(sha256sum "$ROOT/launcher/resource_bind.py" | cut -c1-64)"
echo "ROOT_TOP: $(ls "$ROOT" | tr '\n' ' ')"
echo "REDEPLOY_COMPLETE submissions=0 deletions=0"
